// Media-UI screenshot harness: serve the built frontend, drive
// headless Chrome over CDP (Node 24 built-in WebSocket, no deps),
// screenshot (a) the live Calls panel + the P2P panel's media
// section at desktop + 390px, and (b) the static state snapshots
// (ringing / active desktop / active Android-relayed / group
// mixer / group self-mixer) generated by media-ui-snapshots.mjs.
// Usage: node scripts/media-ui-shots.mjs <dist-dir> <out-dir>
// (run after `npm run build` + media-ui-snapshots.mjs; deletes
// dist/.media-shots/ afterwards — snapshots are throwaway).
import { spawn, execSync } from "node:child_process";
import { writeFileSync, mkdirSync, rmSync, existsSync } from "node:fs";
import http from "node:http";
import { readFile } from "node:fs/promises";
import path from "node:path";

const [distDir, outDir] = process.argv.slice(2);
if (!distDir || !outDir) {
  console.error("usage: node scripts/media-ui-shots.mjs <dist-dir> <out-dir>");
  process.exit(2);
}
mkdirSync(outDir, { recursive: true });
const t0 = Date.now();
const log = (...a) => console.log(`[+${((Date.now() - t0) / 1000).toFixed(1)}s]`, ...a);
function withTimeout(promise, ms, label) {
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(() => reject(new Error(`TIMEOUT after ${ms}ms: ${label}`)), ms)),
  ]);
}

const MIME = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".svg": "image/svg+xml", ".json": "application/json" };
const server = http.createServer(async (req, res) => {
  try {
    const urlPath = decodeURIComponent(new URL(req.url ?? "/", "http://x").pathname);
    let file = path.join(distDir, urlPath === "/" ? "index.html" : urlPath);
    if (!file.startsWith(distDir)) throw new Error("bad path");
    const data = await readFile(file);
    res.writeHead(200, { "content-type": MIME[path.extname(file)] ?? "application/octet-stream" });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end("not found");
  }
});
await new Promise((r) => server.listen(0, "127.0.0.1", r));
const port = server.address().port;
const base = `http://127.0.0.1:${port}/`;
log("serving", base);

const CHROME = `${process.env.HOME}/.cache/puppeteer/chrome/linux-156.0.8078.47/chrome-linux64/chrome`;
const CDP_PORT = 9445;
const chrome = spawn(CHROME, [
  "--headless=new",
  "--no-sandbox",
  "--disable-gpu",
  `--remote-debugging-port=${CDP_PORT}`,
  "--user-data-dir=/tmp/media-ui-shots-profile",
  "about:blank",
], { stdio: ["ignore", "pipe", "pipe"] });
chrome.stderr.on("data", (d) => process.stderr.write(`[chrome] ${d}`));
const cleanup = () => { try { chrome.kill(); } catch {} server.close(); };
process.on("exit", cleanup);

let devtoolsUrl = "";
for (let i = 0; i < 30 && !devtoolsUrl; i++) {
  await new Promise((r) => setTimeout(r, 200));
  try {
    const out = execSync(`curl -s --max-time 2 http://127.0.0.1:${CDP_PORT}/json/version 2>/dev/null || true`, { encoding: "utf8" });
    const m = /"webSocketDebuggerUrl":\s*"([^"]+)"/.exec(out);
    if (m) devtoolsUrl = m[1];
  } catch { /* not up yet */ }
}
if (!devtoolsUrl) {
  console.error("could not reach chrome devtools on", CDP_PORT);
  process.exit(1);
}
log("devtools up:", devtoolsUrl);

const ws = new WebSocket(devtoolsUrl);
await withTimeout(new Promise((resolve, reject) => {
  ws.onopen = resolve;
  ws.onerror = (e) => reject(new Error(`ws error: ${e.message ?? e.type}`));
}), 15000, "websocket open");
log("websocket open");
let msgId = 0;
const pending = new Map();
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  }
};
function send(method, params = {}) {
  return withTimeout(new Promise((resolve) => {
    const id = ++msgId;
    pending.set(id, resolve);
    ws.send(JSON.stringify({ id, method, params }));
  }), 20000, `browser ${method}`);
}
const created = await send("Target.createTarget", { url: "about:blank" });
const attached = await send("Target.attachToTarget", { targetId: created.result.targetId, flatten: true });
const sessionId = attached.result.sessionId;
async function sendSession(method, params = {}) {
  const id = ++msgId;
  const promise = new Promise((resolve) => pending.set(id, resolve));
  ws.send(JSON.stringify({ id, sessionId, method, params }));
  const reply = await withTimeout(promise, 20000, `session ${method}`);
  if (reply.error) throw new Error(`${method}: ${JSON.stringify(reply.error)}`);
  return reply.result;
}
async function evalJs(expression) {
  const r = await sendSession("Runtime.evaluate", { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) throw new Error(JSON.stringify(r.exceptionDetails));
  return r.result?.value;
}
async function shot(name) {
  const r = await sendSession("Page.captureScreenshot", { format: "png" });
  writeFileSync(path.join(outDir, name), Buffer.from(r.data, "base64"));
  log("wrote", name);
}
async function overflow() {
  return evalJs(`({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth, hOverflow: document.documentElement.scrollWidth > document.documentElement.clientWidth })`);
}
async function setDesktop() {
  await sendSession("Emulation.setDeviceMetricsOverride", { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });
}
async function setMobile() {
  await sendSession("Emulation.setDeviceMetricsOverride", { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
}

await sendSession("Page.enable");
await sendSession("Runtime.enable");

// --- Live app: Calls panel (idle, guest — no identity) ---
await setDesktop();
await sendSession("Page.navigate", { url: base });
await new Promise((r) => setTimeout(r, 2500));
const callsNav = await evalJs(`!!document.querySelector('button[data-panel="calls"]')`);
log("calls nav button present:", callsNav);
if (!callsNav) {
  log("page text:", await evalJs(`document.body.innerText.slice(0, 500)`));
  throw new Error("Calls nav button not found");
}
await evalJs(`document.querySelector('button[data-panel="calls"]').click()`);
await new Promise((r) => setTimeout(r, 1500));
await shot("calls-panel-desktop.png");
log("calls desktop overflow:", JSON.stringify(await overflow()));
await setMobile();
await new Promise((r) => setTimeout(r, 800));
await shot("calls-panel-390px.png");
log("calls 390px overflow:", JSON.stringify(await overflow()));

// --- Live app: P2P panel media section ---
await setDesktop();
await evalJs(`document.querySelector('button[data-panel="p2p"]')?.click()`);
await new Promise((r) => setTimeout(r, 1200));
await evalJs(`[...document.querySelectorAll('h2, h3')].find(e => e.textContent.includes('Calls (real-time media)'))?.scrollIntoView({block:'start'})`);
await new Promise((r) => setTimeout(r, 600));
await shot("p2p-media-section-desktop.png");
log("p2p desktop overflow:", JSON.stringify(await overflow()));
await setMobile();
await new Promise((r) => setTimeout(r, 800));
await evalJs(`[...document.querySelectorAll('h2, h3')].find(e => e.textContent.includes('Calls (real-time media)'))?.scrollIntoView({block:'start'})`);
await new Promise((r) => setTimeout(r, 600));
await shot("p2p-media-section-390px.png");
log("p2p 390px overflow:", JSON.stringify(await overflow()));

// --- Static state snapshots ---
const snaps = ["snap-ringing", "snap-active-desktop", "snap-active-android", "snap-group-mixer", "snap-group-self-mixer"];
for (const name of snaps) {
  const url = `${base}.media-shots/${name}.html`;
  await setDesktop();
  await sendSession("Page.navigate", { url });
  await new Promise((r) => setTimeout(r, 1200));
  await shot(`${name}-desktop.png`);
  log(name, "desktop overflow:", JSON.stringify(await overflow()));
  await setMobile();
  await new Promise((r) => setTimeout(r, 800));
  await shot(`${name}-390px.png`);
  log(name, "390px overflow:", JSON.stringify(await overflow()));
}

ws.close();
chrome.kill();
server.close();
rmSync(path.join(distDir, ".media-shots"), { recursive: true, force: true });
log("done");
process.exit(0);
